code='''from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    frame_cells = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            r0, r1 = min(y for y,x in comp), max(y for y,x in comp)
            c0, c1 = min(x for y,x in comp), max(x for y,x in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                         if y in (r0,r1) or x in (c0,c1)}
            if set(comp) == perimeter:
                frames.append((color,r0,r1,c0,c1))
                frame_cells.update(comp)
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] != 0 and (r,c) not in frame_cells)
    out = [[0]*w for _ in range(h)]
    for color,r0,r1,c0,c1 in frames:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                out[r][c] = color
        ih, iw = r1-r0-1, c1-c0-1
        needed = (ih*iw + 1)//2
        fill = next((col for col,n in counts.items() if n == needed), None)
        if fill is not None:
            for r in range(r0+1,r1):
                for c in range(c0+1,c1):
                    if ((r-(r0+1)) + (c-(c0+1))) % 2 == 0:
                        out[r][c] = fill
    return out
'''
